`timescale 1ns/1ps

// Self-checking testbench for sthamly_top (generated by verilog_writer.py).
// For each frame: random weights/activations go in, and the accumulator is
// compared with a software model computed here using the same mask.
// The values below must match the generated file (8x8 grid, 8 bits, 2 frames).
module tb_top;
    localparam N      = 64;   // rows * cols
    localparam BITS   = 8;
    localparam FRAMES = 2;
    localparam FS     = 1;    // frame_sel width: max(1, bit_length(FRAMES-1))
    localparam CYCLES = 5;    // accumulate cycles tested per frame

    reg                 clk = 0;
    reg                 rst = 1;
    reg                 clear = 0;
    reg                 en = 0;
    reg  [FS-1:0]       frame_sel = 0;
    reg  [N*BITS-1:0]   w_flat = 0;
    reg  [N*BITS-1:0]   a_flat = 0;
    wire signed [31:0]  acc;
    wire [31:0]         passes;

    sthamly_top dut (
        .clk(clk), .rst(rst), .clear(clear), .en(en),
        .frame_sel(frame_sel),
        .w_flat(w_flat), .a_flat(a_flat),
        .acc(acc), .passes(passes)
    );

    always #5 clk = ~clk;

    integer seed = 1;
    integer f, c, i;
    integer errors = 0;
    integer checks = 0;
    reg signed [31:0]     expected;
    reg signed [31:0]     term;
    reg signed [BITS-1:0] w, a;
    reg [N-1:0]           m;

    initial begin
        // reset
        repeat (2) @(posedge clk);
        #1 rst = 0;

        for (f = 0; f < FRAMES; f = f + 1) begin
            // clear accumulator and select frame
            clear = 1; @(posedge clk); #1 clear = 0;
            frame_sel = f;
            #1;
            m = dut.mask;
            expected = 0;
            $display("frame %0d: mask=%h passes=%0d", f, m, passes);

            for (c = 0; c < CYCLES; c = c + 1) begin
                for (i = 0; i < N; i = i + 1) begin
                    w_flat[i*BITS +: BITS] = $random(seed);
                    a_flat[i*BITS +: BITS] = $random(seed);
                end
                #1;
                term = 0;
                for (i = 0; i < N; i = i + 1) begin
                    if (m[i]) begin
                        w = w_flat[i*BITS +: BITS];
                        a = a_flat[i*BITS +: BITS];
                        term = term + w * a;
                    end
                end
                expected = expected + term;

                en = 1; @(posedge clk); #1 en = 0;

                checks = checks + 1;
                if (acc !== expected) begin
                    errors = errors + 1;
                    $display("MISMATCH frame %0d cycle %0d: got %0d expected %0d",
                             f, c, acc, expected);
                end
            end
        end

        // clear must bring the accumulator back to 0
        clear = 1; @(posedge clk); #1 clear = 0;
        checks = checks + 1;
        if (acc !== 0) begin
            errors = errors + 1;
            $display("MISMATCH after clear: acc=%0d", acc);
        end

        if (errors == 0) $display("PASS: %0d checks, 0 errors", checks);
        else             $display("FAIL: %0d errors in %0d checks", errors, checks);
        $finish;
    end
endmodule